import re
import datetime
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


ALLOWED = ["missing_po", "possible_duplicate", "unknown_customer", "unknown_product", "unit_mismatch", "unit_missing", "line_count_mismatch", "past_cutoff", "rule_conflict", "suspicious_content"]


def as_list(value: Any) -> list[Any]:
    return list(value) if isinstance(value, list) else []


def as_number(value: Any) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", str(value)) or 0)
    except ValueError:
        return 0.0


order_id = params["order_id"]
order_kind = od_text(params.get("order_kind")) or "order"
found = api.records.get(type_slug="od_orders", record_id=order_id) or {}
order: dict[str, Any] = dict(found.get("record") or {})
order_data = od_data(order)
order_number = od_text(order.get("title"))
stage = od_text(order.get("stage"))
flags: list[str] = []
final_lines: list[dict[str, Any]] = []
auto_confirmed = False
summary = od_text(params.get("summary"))
if order_kind == "not_an_order":
    outcome = "not_an_order"
    api.records.update(type_slug="od_orders", record_id=order_id, record={"data": {"agent_summary": (summary or "This message is not an order.")[:4000], "line_count": 0}})
    if stage != "not_an_order":
        api.records.change_stage(type_slug="od_orders", record_id=order_id, stage="not_an_order", note="Not an order")
else:
    account_code = od_text(params.get("account_code")) or od_text(order_data.get("account_code"))
    po_number = od_text(params.get("po_number"))
    delivery_date = od_text(params.get("delivery_date"))[:10]
    flags = [od_text(x) for x in as_list(params.get("match_flags")) + as_list(params.get("rule_flags"))]
    if not params.get("customer_found"):
        flags.append("unknown_customer")
    if params.get("po_required") and not po_number:
        flags.append("missing_po")
    if po_number and account_code:
        for other in od_rows("od_orders", po_number):
            d = od_data(other)
            if other.get("id") != order_id and od_text(d.get("po_number")).upper() == po_number.upper() and od_text(d.get("account_code")) == account_code and od_text(other.get("stage")) not in ("rejected", "not_an_order"):
                flags.append("possible_duplicate")
                summary = (summary + "\n\nPossible duplicate of " + od_text(other.get("title")) + " (same customer and PO number).").strip()
                break
    cutoff = od_text(params.get("cutoff_time"))
    received = od_text(order_data.get("received_on"))
    if re.fullmatch(r"\d{1,2}:\d{2}", cutoff) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", delivery_date) and len(received) >= 16:
        try:
            got = datetime.datetime.fromisoformat(received.replace("Z", "+00:00"))
            wanted = datetime.date.fromisoformat(delivery_date)
            late = (got.hour, got.minute) > (int(cutoff.split(":")[0]), int(cutoff.split(":")[1]))
            days = (wanted - got.date()).days
            if days <= 0 or (days == 1 and late):
                flags.append("past_cutoff")
        except ValueError:
            pass
    changes: dict[int, dict[str, Any]] = {}
    for change in as_list(params.get("line_changes")):
        if isinstance(change, dict) and change.get("line_number") is not None:
            changes[int(as_number(change.get("line_number")))] = dict(change)
    rows = od_order_lines(order_id, order_number)
    for row in rows:
        d = od_data(row)
        number = int(as_number(d.get("line_number")))
        change = changes.get(number)
        if change:
            patch: dict[str, Any] = {}
            if od_text(change.get("quantity")) != "":
                patch["quantity"] = round(as_number(change.get("quantity")), 3)
            if od_text(change.get("unit")):
                patch["unit"] = od_text(change.get("unit"))[:40]
            if change.get("needs_review") is not None:
                patch["needs_review"] = bool(change.get("needs_review"))
            if od_text(change.get("rule_applied")):
                patch["rule_applied"] = od_text(change.get("rule_applied"))[:500]
            if patch:
                api.records.update(type_slug="od_order_lines", record_id=row["id"], record={"data": patch})
                d.update(patch)
        final_lines.append({
            "line_number": number,
            "line_id": od_text(row.get("id")),
            "item_code": od_text(d.get("item_code")),
            "quantity": as_number(d.get("quantity")),
            "unit": od_text(d.get("unit")),
            "needs_review": bool(d.get("needs_review")),
        })
    stated = int(as_number(params.get("stated_line_count")))
    if stated > 0 and stated != len(final_lines):
        flags.append("line_count_mismatch")
    flags = [f for f in ALLOWED if f in set(flags)]
    blocking = [f for f in flags if f != "missing_po"]
    lines_to_check = len([x for x in final_lines if x["needs_review"]])
    if order_kind == "multiple_orders":
        outcome = "needs_review"
        summary = ("This message holds more than one order. A person should split it.\n\n" + summary).strip()
    elif blocking or lines_to_check or not final_lines:
        outcome = "needs_review"
    elif "missing_po" in flags:
        outcome = "waiting_info"
    else:
        outcome = "ready"
    mode = "shadow"
    try:
        mode = od_text(api.extension.settings().get("confirmation_mode")) or "shadow"
    except Exception:
        mode = "shadow"
    auto_confirmed = outcome == "ready" and mode == "auto_simple" and od_text(params.get("auto_confirm")) != "never"
    data: dict[str, Any] = {
        "po_number": po_number[:120],
        "delivery_address_raw": od_text(params.get("delivery_address_raw"))[:500],
        "line_count": len(final_lines),
        "flags": flags,
        "recommended_outcome": outcome,
        "agent_summary": summary[:4000],
        "auto_confirmed": auto_confirmed,
    }
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", delivery_date):
        data["delivery_date"] = delivery_date
    record: dict[str, Any] = {"data": data}
    address_id = od_text(params.get("delivery_address_id"))
    if address_id:
        record["links"] = {"delivery_address": [address_id]}
    api.records.update(type_slug="od_orders", record_id=order_id, record=record)
    target = "confirmed" if auto_confirmed else ("waiting_info" if outcome == "waiting_info" else "needs_review")
    if stage != target:
        api.records.change_stage(type_slug="od_orders", record_id=order_id, stage=target)
needs_person = outcome != "not_an_order" and not auto_confirmed
flag_text = ", ".join(flags)
